export const SEED_EMPLOYEES = DK_EMPLOYEES_COMPACT_174.map(([
  full_name,
  employee_no,
  department,
  join_date,
  position,
  contract_start_date,
  contract_end_date,
  address,
  ktp_nik,
  birth_place,
  birth_date,
  phone,
  employment_status,
  education,
  gender,
  religion,
  home_base,
  company_entity
], idx) => ({
  id: `emp-dk-${String(idx + 1).padStart(3, '0')}`,
  applicant_id: null,
  employee_no,
  full_name,
  department,
  position,
  employment_status,
  join_date,
  contract_start_date,
  contract_end_date,
  address: address || '',
  ktp_nik: ktp_nik || '',
  birth_place: birth_place || '',
  birth_date,
  phone: phone || '',
  education: education || '',
  gender: gender || '',
  religion: religion || '',
  home_base: String(home_base || 'PASURUAN').trim().toUpperCase(),
  company_entity: String(company_entity || 'MITRA').trim().toUpperCase(),
  salary: String(position || '').toUpperCase().includes('SOPIR') ? 3675000 : null,
  notes: employee_no === 'ST 140807' ? 'Driver Kontainer (dikecualikan dari modul Driver Payroll)' : ''
}));

